export interface ScheduledTask {
  id: string;
  prompt: string;
  cron: string;
  recurring: boolean;
  durable: boolean;
  createdAt: Date;
  lastFiredAt?: Date;
  nextFireAt: Date;
  agentId?: string;
}

export interface CreateScheduleInput {
  prompt: string;
  cron: string;
  recurring?: boolean;
  durable?: boolean;
  agentId?: string;
}

export interface WakeupInput {
  prompt: string;
  delay: string;
}

export interface ScheduleClock {
  now(): Date;
  setTimeout(callback: () => void, delayMs: number): ReturnType<typeof setTimeout>;
  clearTimeout(timer: ReturnType<typeof setTimeout>): void;
}

export type PromptSink = (prompt: string, task: Readonly<ScheduledTask>) => void | Promise<void>;

import { join } from "node:path";
import { humanReadableCron, nextCronTime, parseDelay, validateCron } from "./cron.js";
import { ScheduleStore } from "./store.js";
import type { CreateScheduleInput, PromptSink, ScheduleClock, ScheduledTask, WakeupInput } from "./types.js";

const MAX_TIMER_MS = 2_147_000_000;
const MAX_PROMPT_LENGTH = 100_000;
const DEFAULT_CLOCK: ScheduleClock = {
  now: () => new Date(),
  setTimeout: (callback, delayMs) => setTimeout(callback, delayMs),
  clearTimeout: (timer) => clearTimeout(timer),
};

export interface SchedulerOptions {
  workDir?: string;
  store?: ScheduleStore;
  sink: PromptSink;
  clock?: ScheduleClock;
  onError?: (error: unknown) => void;
  idFactory?: (kind: "task" | "wakeup") => string;
}

function copy(task: ScheduledTask): ScheduledTask {
  return {
    ...task,
    createdAt: new Date(task.createdAt),
    nextFireAt: new Date(task.nextFireAt),
    lastFiredAt: task.lastFiredAt ? new Date(task.lastFiredAt) : undefined,
  };
}

function prompt(value: string): string {
  if (typeof value !== "string" || !value.trim()) throw new Error("prompt parameter is required");
  if (value.length > MAX_PROMPT_LENGTH) throw new Error(`prompt exceeds ${MAX_PROMPT_LENGTH} characters`);
  return value;
}

function agentId(value: string | undefined): string | undefined {
  if (value === undefined || value === "") return undefined;
  if (typeof value !== "string" || value.length > 256 || /[\0\r\n]/.test(value)) {
    throw new Error("agent_id must be a single string of at most 256 characters");
  }
  return value;
}

export class Scheduler {
  private readonly tasks = new Map<string, ScheduledTask>();
  private readonly store: ScheduleStore;
  private readonly clock: ScheduleClock;
  private readonly sink: PromptSink;
  private readonly onError: (error: unknown) => void;
  private readonly idFactory: (kind: "task" | "wakeup") => string;
  private timer?: ReturnType<typeof setTimeout>;
  private started = false;
  private mutation: Promise<void> = Promise.resolve();
  private firing: Promise<void> = Promise.resolve();

  constructor(options: SchedulerOptions) {
    if (typeof options.sink !== "function") throw new Error("prompt sink is required");
    this.store = options.store ?? new ScheduleStore(join(options.workDir ?? process.cwd(), ".swarm", "scheduled_tasks.json"));
    this.clock = options.clock ?? DEFAULT_CLOCK;
    this.sink = options.sink;
    this.onError = options.onError ?? ((error) => console.error("[schedule]", error));
    this.idFactory = options.idFactory ?? ((kind) => `${kind}-${crypto.randomUUID()}`);
  }

  async start(): Promise<void> {
    await this.exclusive(async () => {
      if (this.started) return;
      const loaded = await this.store.load();
      for (const task of loaded) this.tasks.set(task.id, task);
      this.started = true;
      this.arm();
    });
  }

  async stop(): Promise<void> {
    await this.exclusive(async () => {
      this.started = false;
      if (this.timer) this.clock.clearTimeout(this.timer);
      this.timer = undefined;
      this.tasks.clear();
    });
  }

  async create(input: CreateScheduleInput): Promise<ScheduledTask> {
    return this.exclusive(async () => {
      this.assertStarted();
      const now = this.clock.now();
      const cron = validateCron(input.cron);
      const task: ScheduledTask = {
        id: this.uniqueId("task"),
        prompt: prompt(input.prompt),
        cron,
        recurring: input.recurring ?? false,
        durable: input.durable ?? false,
        createdAt: now,
        nextFireAt: nextCronTime(cron, now),
        agentId: agentId(input.agentId),
      };
      this.tasks.set(task.id, task);
      try {
        await this.persist();
      } catch (error) {
        this.tasks.delete(task.id);
        throw error;
      }
      this.arm();
      return copy(task);
    });
  }

  async scheduleWakeup(input: WakeupInput): Promise<ScheduledTask & { delay: string }> {
    return this.exclusive(async () => {
      this.assertStarted();
      const now = this.clock.now();
      const delayMs = parseDelay(input.delay);
      const fireAt = new Date(now.getTime() + delayMs);
      const task: ScheduledTask = {
        id: this.uniqueId("wakeup"),
        prompt: prompt(input.prompt),
        cron: `${fireAt.getMinutes()} ${fireAt.getHours()} ${fireAt.getDate()} ${fireAt.getMonth() + 1} *`,
        recurring: false,
        durable: false,
        createdAt: now,
        nextFireAt: fireAt,
      };
      this.tasks.set(task.id, task);
      this.arm();
      return { ...copy(task), delay: input.delay };
    });
  }

  async remove(id: string): Promise<ScheduledTask> {
    return this.exclusive(async () => {
      this.assertStarted();
      if (typeof id !== "string" || !id.trim()) throw new Error("id parameter is required");
      const task = this.tasks.get(id);
      if (!task) throw new Error(`scheduled task '${id}' not found`);
      this.tasks.delete(id);
      try {
        await this.persist();
      } catch (error) {
        this.tasks.set(id, task);
        throw error;
      }
      this.arm();
      return copy(task);
    });
  }

  list(): ScheduledTask[] {
    return [...this.tasks.values()]
      .sort((a, b) => a.nextFireAt.getTime() - b.nextFireAt.getTime() || a.id.localeCompare(b.id))
      .map(copy);
  }

  /** Wait until pending persistence and prompt delivery have settled. */
  async idle(): Promise<void> {
    await this.mutation;
    await this.firing;
    await this.mutation;
  }

  describe(task: ScheduledTask): Record<string, unknown> {
    return {
      id: task.id,
      cron: task.cron,
      human_schedule: humanReadableCron(task.cron),
      type: task.recurring ? "recurring" : "one-shot",
      persistence: task.durable ? "durable" : "session",
      next_fire_at: task.nextFireAt.toISOString(),
      ...(task.agentId ? { agent_id: task.agentId } : {}),
    };
  }

  private assertStarted(): void {
    if (!this.started) throw new Error("scheduler is not started");
  }

  private uniqueId(kind: "task" | "wakeup"): string {
    for (let attempt = 0; attempt < 10; attempt++) {
      const id = this.idFactory(kind);
      if (/^(?:task|wakeup)-[a-zA-Z0-9-]{8,}$/.test(id) && !this.tasks.has(id)) return id;
    }
    throw new Error("failed to generate a unique schedule id");
  }

  private async persist(): Promise<void> {
    await this.store.save([...this.tasks.values()]);
  }

  private arm(): void {
    if (this.timer) this.clock.clearTimeout(this.timer);
    this.timer = undefined;
    if (!this.started || !this.tasks.size) return;
    const next = Math.min(...[...this.tasks.values()].map((task) => task.nextFireAt.getTime()));
    const delay = Math.max(0, Math.min(next - this.clock.now().getTime(), MAX_TIMER_MS));
    this.timer = this.clock.setTimeout(() => {
      this.timer = undefined;
      const firing = this.fireDue();
      this.firing = firing.then(() => undefined, (error) => this.onError(error));
    }, delay);
    (this.timer as { unref?: () => void }).unref?.();
  }

  private async fireDue(): Promise<void> {
    const due = await this.exclusive(async () => {
      if (!this.started) return [];
      const now = this.clock.now();
      const claimed: ScheduledTask[] = [];
      for (const task of this.tasks.values()) {
        if (task.nextFireAt.getTime() > now.getTime()) continue;
        claimed.push(copy(task));
        if (task.recurring) {
          task.lastFiredAt = now;
          task.nextFireAt = nextCronTime(task.cron, now);
        } else {
          this.tasks.delete(task.id);
        }
      }
      if (claimed.length) await this.persist();
      this.arm();
      return claimed;
    });
    await Promise.allSettled(due.map(async (task) => {
      try {
        await this.sink(task.prompt, task);
      } catch (error) {
        this.onError(error);
      }
    }));
  }

  private exclusive<T>(operation: () => Promise<T>): Promise<T> {
    const result = this.mutation.then(operation, operation);
    this.mutation = result.then(() => undefined, () => undefined);
    return result;
  }
}

import { chmod, mkdir, readFile, rename, rm, writeFile } from "node:fs/promises";
import { dirname } from "node:path";
import type { ScheduledTask } from "./types.js";
import { validateCron } from "./cron.js";

interface StoredTask {
  id: string;
  prompt: string;
  cron: string;
  recurring: boolean;
  durable: boolean;
  created_at: string;
  last_fired_at?: string;
  agent_id?: string;
  next_fire_at: string;
}

function validDate(value: unknown, field: string, required: boolean): Date | undefined {
  if ((value === undefined || value === "") && !required) return undefined;
  if (typeof value !== "string") throw new Error(`${field} must be an ISO date`);
  const date = new Date(value);
  if (!Number.isFinite(date.getTime())) throw new Error(`${field} must be an ISO date`);
  return date;
}

function decode(value: unknown, index: number): ScheduledTask {
  if (!value || typeof value !== "object" || Array.isArray(value)) {
    throw new Error(`task ${index} must be an object`);
  }
  const raw = value as Partial<StoredTask>;
  if (typeof raw.id !== "string" || !/^(?:task|wakeup)-[a-zA-Z0-9-]{8,}$/.test(raw.id)) {
    throw new Error(`task ${index} has an invalid id`);
  }
  if (typeof raw.prompt !== "string" || !raw.prompt.trim()) throw new Error(`task ${raw.id} has no prompt`);
  if (raw.prompt.length > 100_000) throw new Error(`task ${raw.id} prompt is too long`);
  if (raw.durable !== true) throw new Error(`persisted task ${raw.id} must be durable`);
  if (typeof raw.recurring !== "boolean") throw new Error(`task ${raw.id} recurring must be boolean`);
  const createdAt = validDate(raw.created_at, "created_at", true)!;
  const lastFiredAt = validDate(raw.last_fired_at, "last_fired_at", false);
  const nextFireAt = validDate(raw.next_fire_at, "next_fire_at", true)!;
  return {
    id: raw.id,
    prompt: raw.prompt,
    cron: validateCron(String(raw.cron ?? "")),
    recurring: raw.recurring,
    durable: true,
    createdAt,
    lastFiredAt,
    nextFireAt,
    agentId: typeof raw.agent_id === "string" && raw.agent_id ? raw.agent_id : undefined,
  };
}

function encode(task: ScheduledTask): StoredTask {
  return {
    id: task.id,
    prompt: task.prompt,
    cron: task.cron,
    recurring: task.recurring,
    durable: task.durable,
    created_at: task.createdAt.toISOString(),
    ...(task.lastFiredAt ? { last_fired_at: task.lastFiredAt.toISOString() } : {}),
    ...(task.agentId ? { agent_id: task.agentId } : {}),
    next_fire_at: task.nextFireAt.toISOString(),
  };
}

export class ScheduleStore {
  constructor(readonly path: string) {}

  async load(): Promise<ScheduledTask[]> {
    let text: string;
    try {
      text = await readFile(this.path, "utf8");
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return [];
      throw new Error(`failed to read schedule store: ${String(error)}`, { cause: error });
    }
    let raw: unknown;
    try {
      raw = JSON.parse(text);
    } catch (error) {
      throw new Error(`schedule store is not valid JSON: ${this.path}`, { cause: error });
    }
    if (!Array.isArray(raw)) throw new Error("schedule store root must be an array");
    const tasks = raw.map(decode);
    const ids = new Set<string>();
    for (const task of tasks) {
      if (ids.has(task.id)) throw new Error(`schedule store contains duplicate id ${task.id}`);
      ids.add(task.id);
    }
    return tasks;
  }

  async save(tasks: readonly ScheduledTask[]): Promise<void> {
    const durable = tasks.filter((task) => task.durable).sort((a, b) => a.id.localeCompare(b.id));
    if (!durable.length) {
      await rm(this.path, { force: true });
      return;
    }
    await mkdir(dirname(this.path), { recursive: true, mode: 0o700 });
    const temporary = `${this.path}.tmp-${process.pid}-${crypto.randomUUID()}`;
    try {
      await writeFile(temporary, `${JSON.stringify(durable.map(encode), null, 2)}\n`, {
        encoding: "utf8",
        mode: 0o600,
        flag: "wx",
      });
      await rename(temporary, this.path);
      await chmod(this.path, 0o600);
    } finally {
      await rm(temporary, { force: true });
    }
  }
}

import type { Scheduler } from "./scheduler.js";

interface ToolResult {
  content: Array<{ type: "text"; text: string }>;
  details: unknown;
  isError?: boolean;
}

const objectSchema = { type: "object", additionalProperties: false } as const;
const text = (details: unknown, message?: string): ToolResult => ({
  content: [{ type: "text", text: message ?? JSON.stringify(details, null, 2) }],
  details,
});
const failure = (error: unknown): ToolResult => ({
  content: [{ type: "text", text: error instanceof Error ? error.message : String(error) }],
  details: { error: error instanceof Error ? error.message : String(error) },
  isError: true,
});

function executable<T>(run: (params: T) => Promise<ToolResult>) {
  return async (_toolCallId: string, params: T): Promise<ToolResult> => {
    try {
      return await run(params);
    } catch (error) {
      return failure(error);
    }
  };
}

export interface ScheduleToolAPI {
  registerTool(tool: unknown): void;
}

export function registerScheduleTools(pi: ScheduleToolAPI, scheduler: Scheduler): void {
  pi.registerTool({
    name: "cron_create",
    label: "Create schedule",
    description: "Schedule a prompt to run at a future time, either recurring on a standard five-field cron schedule or once at its next occurrence.",
    promptSnippet: "Create recurring or one-shot prompt schedules",
    executionMode: "parallel",
    parameters: {
      ...objectSchema,
      required: ["prompt", "cron"],
      properties: {
        prompt: { type: "string", minLength: 1, maxLength: 100_000, description: "The prompt to execute on the scheduled agent." },
        cron: { type: "string", minLength: 1, maxLength: 256, description: "Standard five-field cron: minute hour day-of-month month day-of-week." },
        recurring: { type: "boolean", default: false, description: "Keep scheduling after the first occurrence." },
        durable: { type: "boolean", default: false, description: "Persist across process restarts." },
        agent_id: { type: "string", maxLength: 256, description: "Optional target agent identity." },
      },
    },
    execute: executable(async (params: { prompt: string; cron: string; recurring?: boolean; durable?: boolean; agent_id?: string }) => {
      const task = await scheduler.create({ ...params, agentId: params.agent_id });
      const details = scheduler.describe(task);
      return text(details, JSON.stringify({
        ...details,
        message: `Scheduled ${details.type} task ${task.id} (${details.human_schedule}). ${task.durable ? "persisted" : "session-only"}.`,
      }, null, 2));
    }),
  });

  pi.registerTool({
    name: "cron_list",
    label: "List schedules",
    description: "List scheduled cron jobs with IDs, expressions, schedule type, persistence, and next fire time.",
    promptSnippet: "List active prompt schedules",
    executionMode: "parallel",
    parameters: { ...objectSchema, properties: {} },
    execute: executable(async () => {
      const tasks = scheduler.list().map((task) => scheduler.describe(task));
      const details = { total_tasks: tasks.length, tasks };
      if (!tasks.length) return text(details, `No scheduled tasks.\n\n${JSON.stringify(details, null, 2)}`);
      const lines = tasks.map((task) =>
        `  ${task.id}: ${task.human_schedule} (${task.type}, ${task.persistence})\n    Cron: ${task.cron}\n    Next: ${task.next_fire_at}`,
      );
      return text(details, `Scheduled Tasks (${tasks.length} total):\n\n${lines.join("\n\n")}\n\n${JSON.stringify(details, null, 2)}`);
    }),
  });

  pi.registerTool({
    name: "cron_delete",
    label: "Delete schedule",
    description: "Cancel a scheduled cron job by ID, including its persisted record when durable.",
    promptSnippet: "Cancel a prompt schedule by ID",
    executionMode: "parallel",
    parameters: {
      ...objectSchema,
      required: ["id"],
      properties: { id: { type: "string", minLength: 1, description: "Task ID to cancel." } },
    },
    execute: executable(async (params: { id: string }) => {
      await scheduler.remove(params.id);
      return text({ id: params.id, message: `Cancelled scheduled task ${params.id}` });
    }),
  });

  pi.registerTool({
    name: "schedule_wakeup",
    label: "Schedule wakeup",
    description: "Schedule a one-shot prompt after a positive delay. Wakeups are session-only.",
    promptSnippet: "Wake the current agent after a delay",
    executionMode: "parallel",
    parameters: {
      ...objectSchema,
      required: ["prompt", "delay"],
      properties: {
        prompt: { type: "string", minLength: 1, maxLength: 100_000, description: "The prompt to execute on wakeup." },
        delay: { type: "string", minLength: 1, description: "Positive Go-style duration such as 30s, 5m, 1h, or 1h30m." },
      },
    },
    execute: executable(async (params: { prompt: string; delay: string }) => {
      const task = await scheduler.scheduleWakeup(params);
      return text({
        id: task.id,
        delay: task.delay,
        fire_time: task.nextFireAt.toISOString(),
        message: `Scheduled wakeup ${task.id} in ${task.delay} (at ${task.nextFireAt.toISOString()}).`,
      });
    }),
  });
}

import { resolve } from "node:path";
import { registerScheduleTools, Scheduler, type SchedulerOptions } from "../../schedule/src/index.ts";

export interface ScheduleExtensionAPI {
  getCwd?(): string;
  registerTool(tool: unknown): void;
  sendUserMessage(content: string, options?: { deliverAs?: "steer" | "followUp" }): void | Promise<void>;
  on?(event: string, handler: (...args: any[]) => unknown): void;
}

export interface ScheduleExtensionOptions extends Omit<SchedulerOptions, "sink" | "workDir"> {
  workDir?: string;
}

export async function registerScheduleExtension(
  pi: ScheduleExtensionAPI,
  options: ScheduleExtensionOptions = {},
): Promise<Scheduler> {
  const workDir = resolve(options.workDir ?? pi.getCwd?.() ?? process.cwd());
  const scheduler = new Scheduler({
    ...options,
    workDir,
    sink: async (prompt) => {
      await pi.sendUserMessage(prompt, { deliverAs: "followUp" });
    },
  });
  registerScheduleTools(pi, scheduler);
  await scheduler.start();
  pi.on?.("session_shutdown", () => scheduler.stop());
  return scheduler;
}

export default async function scheduleExtension(pi: ScheduleExtensionAPI): Promise<void> {
  await registerScheduleExtension(pi);
}

# Workflow runtime

`WorkflowEngine` is an offline, host-agnostic executor for DAG-shaped workflows. The host supplies an `AgentRunner`; the engine provides:

- group dependencies and `parallel`, `sequential`, or `first` strategies;
- per-agent retries and group timeouts;
- attempt, token, and cost budgets;
- `fail_fast` or `continue` failure policy;
- cancellation via `AbortSignal`;
- checkpoint load/save for resume after interruption;
- routing metadata on agents (`route` is passed through to the host runner);
- distinct workflow/group/agent lifecycle events, including completed, failed, and cancelled workflow events.

This is intentionally a small runtime boundary. Provider credentials, model selection, and actual agent execution remain host responsibilities. Checkpoints contain result metadata and outputs supplied by the runner, so hosts should use an appropriate protected store when outputs are sensitive.

# `@pi-swarm/schedule`

Swarm-compatible scheduling for Pi. The package exposes a host-neutral scheduler,
an atomic JSON persistence adapter, and Pi tool registrations:

- `cron_create`
- `cron_list`
- `cron_delete`
- `schedule_wakeup`

Durable tasks are stored in the upstream-compatible
`<workspace>/.swarm/scheduled_tasks.json` array. Session-only tasks and wakeups
remain in memory. Fired prompts are delivered through an injected prompt sink;
the Pi extension uses `sendUserMessage(..., { deliverAs: "followUp" })`.

Cron expressions use standard five-field local-time syntax. A non-recurring
cron fires only at its next matching occurrence. Wakeup delays use the positive
subset of Go duration syntax (`30s`, `5m`, `1h30m`) and are capped at one year.

```ts
import { Scheduler } from "@pi-swarm/schedule";

const scheduler = new Scheduler({
  workDir: process.cwd(),
  sink: async (prompt) => console.log(prompt),
});
await scheduler.start();
await scheduler.create({ prompt: "daily check", cron: "0 9 * * *", recurring: true, durable: true });
```

export * from "./cron.js";
export * from "./scheduler.js";
export * from "./store.js";
export * from "./tools.js";
export * from "./types.js";

import { Cron, CronPattern } from "croner";

const COMMON_SCHEDULES: Readonly<Record<string, string>> = {
  "*/1 * * * *": "every minute",
  "*/5 * * * *": "every 5 minutes",
  "*/15 * * * *": "every 15 minutes",
  "*/30 * * * *": "every 30 minutes",
  "0 * * * *": "every hour",
  "0 */2 * * *": "every 2 hours",
  "0 0 * * *": "daily at midnight",
  "0 0 */1 * *": "daily at midnight",
  "0 9 * * 1-5": "weekdays at 9am",
  "0 9 * * *": "daily at 9am",
};

export function validateCron(expression: string): string {
  const normalized = expression.trim().replace(/\s+/g, " ");
  if (!normalized) throw new Error("cron parameter is required");
  if (normalized.length > 256) throw new Error("cron expression is too long");
  if (normalized.split(" ").length !== 5) {
    throw new Error(`invalid cron expression: ${expression}`);
  }
  try {
    new CronPattern(normalized, undefined, { mode: "5-part" });
  } catch {
    throw new Error(`invalid cron expression: ${expression}`);
  }
  return normalized;
}

export function nextCronTime(expression: string, after: Date): Date {
  const cron = new Cron(validateCron(expression), { paused: true, mode: "5-part" });
  const next = cron.nextRun(after);
  cron.stop();
  if (!next || !Number.isFinite(next.getTime())) {
    throw new Error(`cron expression has no future occurrence: ${expression}`);
  }
  return next;
}

export function humanReadableCron(expression: string): string {
  return COMMON_SCHEDULES[expression] ?? expression;
}

const DURATION_PART = /(\d+(?:\.\d+)?)(ns|us|µs|ms|s|m|h)/gy;
const UNIT_MS: Readonly<Record<string, number>> = {
  ns: 1e-6,
  us: 1e-3,
  "µs": 1e-3,
  ms: 1,
  s: 1_000,
  m: 60_000,
  h: 3_600_000,
};

/** Parse the positive subset of Go's time.ParseDuration syntax used by Swarm. */
export function parseDelay(value: string, maxMs = 365 * 24 * 60 * 60 * 1_000): number {
  const input = value.trim();
  if (!input) throw new Error("delay parameter is required");
  let total = 0;
  let offset = 0;
  DURATION_PART.lastIndex = 0;
  for (;;) {
    const match = DURATION_PART.exec(input);
    if (!match) break;
    if (match.index !== offset) throw new Error(`invalid delay format: ${value}`);
    total += Number(match[1]) * UNIT_MS[match[2]];
    offset = DURATION_PART.lastIndex;
  }
  if (offset !== input.length || !Number.isFinite(total) || total <= 0) {
    throw new Error(`invalid delay format: ${value}`);
  }
  const rounded = Math.ceil(total);
  if (rounded > maxMs) throw new Error(`delay exceeds maximum of ${maxMs}ms`);
  return rounded;
}

import {
  registerTaskHooks,
  registerTaskManage,
  type HookConfig,
  registerInteractionTools,
} from "../../taskmanage/src/index.ts";
import "../hook-state.ts";

/**
 * Minimal structural subset of Pi's ExtensionAPI used by TaskManage.
 *
 * Keeping this adapter structural means the standalone package does not need
 * to depend on a particular Pi release just to remain buildable and testable.
 */
export interface TaskManageExtensionAPI {
  registerTool(tool: unknown): void;
  appendEntry(type: string, data: unknown): void;
  on(
    event: string,
    handler: (
      event: unknown,
      ctx: { sessionManager?: { getEntries(): readonly unknown[] } },
    ) => unknown,
  ): void;
}

export interface TaskManageExtensionOptions extends HookConfig { headless?: boolean; interactionTimeoutMs?: number; }

/**
 * Register the canonical TaskManage tool and its lifecycle coordinator.
 *
 * The manager is intentionally created once per Pi extension instance and is
 * shared by both registrations. Pi reloads create a new instance; the
 * session_start handler rehydrates it from the replacement session manager.
 */
const taskRuntimeByPi = new WeakMap<object, { manager: any; hooks: any; interactions: any }>();
export function registerTaskManageExtension(
  pi: TaskManageExtensionAPI,
  options?: TaskManageExtensionOptions,
) {
  const owner = pi as object;
  const existing = taskRuntimeByPi.get(owner);
  if (existing) return existing;
  const manager = registerTaskManage(pi);
  const hooks = registerTaskHooks(pi, manager, options);
  const interactions = registerInteractionTools(pi as any, { headless: options?.headless, timeoutMs: options?.interactionTimeoutMs });
  const result = { manager, hooks, interactions };
  taskRuntimeByPi.set(owner, result);
  return result;
}

export default function taskManageExtension(pi: TaskManageExtensionAPI): void {
  registerTaskManageExtension(pi);
}

// Package builtin provides cron scheduling infrastructure for recurring and
// one-shot agent tasks.
//
// The scheduler runs a 1-second polling loop that checks all registered tasks
// and fires those whose next cron window has been reached. Jitter is
// proportional to the actual cron gap (10% of the gap between consecutive
// fires, capped at 15 min) so a 1-minute cron gets ~6s of jitter, not 15 min.
//
// Delivery modes (selected via CronSchedulerConfig):
//   - PromptSink: fired prompts are enqueued into the host application's
//     message queue (e.g. the TUI chat queue). The client continues the
//     conversation naturally — the prompt appears as a user message. This
//     mirrors how Claude Code delivers cron-fired prompts via
//     enqueuePendingNotification at 'later' priority. See CRON_SCHEDULER.md.
//   - AgentFactory + BGManager: fired prompts spawn a background agent.
//     Suitable for headless/daemon mode with no interactive chat.
//
// To add a new application that wants to receive cron messages: implement
// the PromptSink interface (one method: EnqueuePrompt), pass it in
// CronSchedulerConfig, and call Start().
package builtin

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/Swarm-Code/mono/swarm-sdk/internal/agent"
	"github.com/Swarm-Code/mono/swarm-sdk/internal/observability"
	"github.com/Swarm-Code/mono/swarm-sdk/internal/provider"
	sdkerr "github.com/Swarm-Code/mono/swarm-sdk/internal/sdkerr"
	"github.com/robfig/cron/v3"
)

// CronJitterConfig configures jitter and expiry behavior for scheduled tasks.
type CronJitterConfig struct {
	RecurringFrac           float64 // fraction of the actual cron gap to jitter (0.1 = 10%)
	RecurringCapMs          int64   // maximum jitter for recurring tasks in milliseconds
	OneShotEarlyJitterMaxMs int64
	RecurringMaxAgeMs       int64
}

// defaultJitterConfig provides default jitter configuration.
var defaultJitterConfig = CronJitterConfig{
	RecurringFrac:           0.1,                     // 10% of the actual cron gap
	RecurringCapMs:          15 * 60 * 1000,          // 15 min cap
	OneShotEarlyJitterMaxMs: 90 * 1000,               // 90s
	RecurringMaxAgeMs:       7 * 24 * 60 * 60 * 1000, // 7 days
}

// PromptSink is an interface for enqueuing fired prompts directly into the host
// application's message queue instead of spawning a background agent.
//
// When configured (via CronSchedulerConfig.PromptSink), fireTaskNow calls
// EnqueuePrompt(ctx, prompt) for each fired task. The host application is
// responsible for routing the prompt to its chat queue, command queue, or
// message bus. This is the recommended delivery mode for interactive apps
// (TUI, REPL) because the prompt enters the same conversation the user is
// having — the client continues naturally between turns.
//
// To add cron support to a new application:
//  1. Implement this interface (EnqueuePrompt).
//  2. Pass your implementation in CronSchedulerConfig.PromptSink.
//  3. Call scheduler.Start().
//
// AgentFactory and BGManager are NOT required when PromptSink is set.
type PromptSink interface {
	EnqueuePrompt(ctx context.Context, prompt string) error
}

// ScheduledTask represents a task to be executed on a schedule.
type ScheduledTask struct {
	ID          string    `json:"id"`
	Prompt      string    `json:"prompt"`
	Cron        string    `json:"cron"`
	Recurring   bool      `json:"recurring"`
	Durable     bool      `json:"durable"`
	CreatedAt   time.Time `json:"created_at"`
	LastFiredAt time.Time `json:"last_fired_at"`
	AgentID     string    `json:"agent_id,omitempty"`
	NextFireAt  time.Time `json:"next_fire_at"`
	AgedOut     bool      `json:"aged_out,omitempty"`
}

// CronScheduler manages scheduled tasks for background agent execution.
type CronScheduler struct {
	tasks         map[string]*ScheduledTask
	mu            sync.RWMutex
	isRunning     bool
	stopChan      chan struct{}
	checkInterval time.Duration

	// Dependencies
	agentFactory agent.Factory
	bgManager    BackgroundAgentManager
	logger       observability.Logger
	workDir      string // For durable task storage
	promptSink   PromptSink

	// runningTasks tracks which task instances are currently executing
	// Key: task.ID, Value: agentID of the spawned background agent
	runningTasks map[string]string
	runningMu    sync.RWMutex
}

// CronSchedulerConfig configures the cron scheduler.
type CronSchedulerConfig struct {
	AgentFactory  agent.Factory
	BGManager     BackgroundAgentManager
	Logger        observability.Logger
	WorkDir       string        // Workspace directory for durable storage
	CheckInterval time.Duration // Default: 1 minute
	PromptSink    PromptSink    // Optional: sink for direct prompt enqueueing
}

// NewCronScheduler creates a new cron scheduler.
func NewCronScheduler(config CronSchedulerConfig) (*CronScheduler, error) {
	// Allow nil AgentFactory and BGManager when PromptSink is provided
	if config.PromptSink == nil {
		if config.AgentFactory == nil {
			return nil, sdkerr.Permanent("cron_scheduler.missing_factory", "agent factory is required")
		}
		if config.BGManager == nil {
			return nil, sdkerr.Permanent("cron_scheduler.missing_manager", "background manager is required")
		}
	}
	if config.Logger == nil {
		return nil, sdkerr.Permanent("cron_scheduler.missing_logger", "logger is required")
	}

	interval := config.CheckInterval
	if interval <= 0 {
		interval = 1 * time.Second // 1s check so sub-minute crons fire promptly
	}

	return &CronScheduler{
		tasks:         make(map[string]*ScheduledTask),
		checkInterval: interval,
		agentFactory:  config.AgentFactory,
		bgManager:     config.BGManager,
		logger:        config.Logger,
		workDir:       config.WorkDir,
		promptSink:    config.PromptSink,
		runningTasks:  make(map[string]string),
	}, nil
}

// Start begins the scheduler loop.
func (s *CronScheduler) Start() {
	s.mu.Lock()
	defer s.mu.Unlock()

	if s.isRunning {
		return
	}

	s.isRunning = true
	s.stopChan = make(chan struct{})

	// Load durable tasks from disk
	s.loadDurableTasks()

	go s.runLoop()

	s.logger.Info(context.Background(), "cron_scheduler.started",
		observability.F("check_interval", s.checkInterval.String()),
		observability.F("task_count", len(s.tasks)))
}

// Stop halts the scheduler loop.
func (s *CronScheduler) Stop() {
	s.mu.Lock()
	if !s.isRunning {
		s.mu.Unlock()
		return
	}

	s.isRunning = false
	close(s.stopChan)
	s.mu.Unlock()

	s.logger.Info(context.Background(), "cron_scheduler.stopped")
}

// runLoop is the main scheduler goroutine. It polls every checkInterval
// (1 second by default) and fires tasks whose next cron window has been
// reached. The 1-second interval ensures sub-minute crons fire promptly;
// the old 1-minute interval could miss a window by up to 59 seconds.
func (s *CronScheduler) runLoop() {
	ticker := time.NewTicker(s.checkInterval)
	defer ticker.Stop()

	for {
		select {
		case <-ticker.C:
			s.checkAndFireTasks()
		case <-s.stopChan:
			return
		}
	}
}

// checkAndFireTasks checks all tasks and fires those that are due.
//
// Firing is a two-phase operation, which is what makes the scheduler robust
// against BOTH the 1-second poll interval AND the asynchronous jitter window:
//
//  1. CLAIM (synchronous, under s.mu): for every due task we immediately record
//     LastFiredAt and advance NextFireAt to the next boundary strictly after
//     `now`, BEFORE dispatching the (possibly jitter-delayed) delivery.
//
//  2. DELIVER (may be async): fireTask applies jitter and enqueues/spawns.
//
// WHY: previously the actual fire — and therefore the LastFiredAt update —
// happened inside fireTaskNow, which fireTask may defer behind an async jitter
// timer (up to ~6s for an every-minute cron). During that window every
// intervening poll still saw the task as due and armed ANOTHER delivery, so a
// single once-per-minute occurrence was delivered ~1×/second (observed 100+
// enqueues per minute in production logs, and the TUI's queue-drain then
// stranded the overflow until the next user interaction). Claiming the
// occurrence up front, in the single scheduler goroutine, guarantees exactly
// one delivery per boundary.
//
// Advancing NextFireAt with schedule.Next(now) also means a delayed poll skips
// past missed boundaries instead of replaying them (no catch-up storm), while
// never skipping the occurrence currently being fired (that one is what made us
// due, and we deliver it before advancing).
func (s *CronScheduler) checkAndFireTasks() {
	now := time.Now()

	var due []*ScheduledTask
	s.mu.Lock()
	for _, task := range s.tasks {
		nextFire, err := s.nextFireLocked(task, now)
		if err != nil {
			s.logger.Warn(context.Background(), "cron_scheduler.calculate_next_fire_failed",
				observability.F("task_id", task.ID),
				observability.F("cron", task.Cron),
				observability.F("error", err.Error()))
			continue
		}
		task.NextFireAt = nextFire
		if !(now.Equal(nextFire) || now.After(nextFire)) {
			continue
		}
		// CLAIM this occurrence so no later poll — and no concurrent jitter
		// timer — can re-arm the same fire.
		task.LastFiredAt = now
		if schedule, perr := cron.ParseStandard(task.Cron); perr == nil {
			task.NextFireAt = schedule.Next(now)
		}
		due = append(due, task)
	}
	s.mu.Unlock()


