// Package builtin provides ScheduleWakeup tool for scheduling one-shot wakeup tasks.
package builtin

import (
	"context"
	"encoding/json"
	"fmt"
	"time"

	"github.com/Swarm-Code/mono/swarm-sdk/internal/observability"
